SELECT  FROM EVAL_TAG

    AND tag_type = #{tagType}
    AND tag_name LIKE CONCAT('%', #{keyword}, '%')

ORDER BY tag_type ASC, tag_id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM EVAL_TAG

    AND tag_type = #{tagType}
    AND tag_name LIKE CONCAT('%', #{keyword}, '%')

SELECT  FROM EVAL_TAG

    AND tag_type = #{tagType}
    AND status = #{status}

ORDER BY tag_type ASC, tag_id ASC
